using System;
using System.Xml;

namespace Resources
{
	/// <summary>
	/// Types should be marked with this attribute only if their source code is auto-generated.
	/// </summary>
	[AttributeUsage(AttributeTargets.Class | AttributeTargets.Struct | AttributeTargets.Interface)]
	public sealed class AutoGeneratedSourceCodeAttribute : Attribute
	{
		public AutoGeneratedSourceCodeAttribute()
		{
		}

		public AutoGeneratedSourceCodeAttribute(string lastGenerated)
		{
			this.LastGenerated = XmlConvert.ToDateTime(lastGenerated, XmlDateTimeSerializationMode.Local);
		}

		public readonly DateTime LastGenerated;
	}
}
